    defragged_task{evidence_sha256:"a2b6eeb767177caed6a3ef83f1e7b77920a0e0e6631ef3f4f7b91f456ffd46c6", status:blocked_layout, blocker:expression_missing_without_visual, complete_statement:"", statement_joiner:" ", statement_segments:[], referents:[], visuals:[], source_segments:[segment{id:"seg_edfe555420ce8e16bc75", path:"curriculum/im/generated/grade_8_extracted_task_instances.pl", line_start:344, line_end:344, byte_start:190540, byte_end:191238, decoder:json_string_ascii, sha256:"ee6eeb43773888e858ad4ab97121c4a9d848b0694293e6825746459daf0e25e2"}], available_fragment:"Your teacher will give you either a problem card or a data card. Do not show or read your card to your partner. If your teacher gives you the problem card: 1. Silently read your card, and think about what information you need to answer the question. 2. Ask your partner for the specific information that you need. 'Can you tell me ?' 3. Explain to your partner how you are using the information to solve the problem. 'I need to know because . . . .' Continue to ask questions until you have enough information to solve the problem. 4. Once you have enough information, share the problem card with your partner, and solve the problem independently. 5. Read the data card, and discuss your reasoning.", fragment_joiner:" ", fragment_segments:[seg_edfe555420ce8e16bc75], source_evidence:task_evidence(rule(docling_task_heading_exact_copy),source('hermes/app/runtime/experiments/gemma4_tutor/docling/full-output/TeacherLessonGuides/Grade8/Grade8-2-5-Lesson-teacher-guide-/document.md',lines(270,281)),position(student_task_statement(2)),excerpt("Your teacher will give you either a problem card or a data card. Do not show or read your card to your partner. If your teacher gives you the problem card: 1. Silently read your card, and think about what information you need to answer the question. 2. Ask your partner for the specific information that you need. 'Can you tell me ?' 3. Explain to your partner how you are using the information to solve the problem. 'I need to know because . . . .' Continue to ask questions until you have enough information to solve the problem. 4. Once you have enough information, share the problem card with your partner, and solve the problem independently. 5. Read the data card, and discuss your reasoning."),extraction_status(blocked_layout),blocker(expression_missing_without_visual),visual_provenance([]))}).

