    defragged_task{evidence_sha256:"4a8387c1d79d99d6461f333f55026446abd20ba89b330159774f4fc23c6af51f", status:already_complete, blocker:none, complete_statement:"Elena borrowed some money from her brother. She pays him back by giving him the same amount every week. 10 min The graph shows how much she owes after each week. Answer and explain your reasoning for each question. 1. What is the slope of the line? 2. Explain how you know whether the slope is positive or negative. 3. What does the slope represent in this situation? 4. How much did Elena borrow? 5. How much time will it take for Elena to pay back all the money she borrowed?", statement_joiner:" ", statement_segments:[seg_7d08c2cfaf5dcbf09f29, seg_ebc6344074aa0def180b, seg_712379073837c8a1db09, seg_6955f944cbe7e63cac2a, seg_c87cc61aec0250c11f3c, seg_4ce8048ac2c7c7a21178, seg_70fd2dd8bb55f5c20957, seg_38072e8547095970ce1d], referents:[referent{surface:"The graph", kind:graph, status:carried_inline, segments:[seg_1958f62d7972f1285b09], antecedent:"Elena borrowed some money from her brother. She pays him back by giving him the same amount every week. 10 min", antecedent_segments:[seg_7d08c2cfaf5dcbf09f29, seg_134c68f5341447c0d1c3], absence_reason:none}], visuals:[], source_segments:[segment{id:"seg_7d08c2cfaf5dcbf09f29", path:"hermes/app/runtime/experiments/gemma4_tutor/docling/full-output/TeacherLessonGuides/Grade8/Grade8-3-10-Lesson-teacher-guide-/document.md", line_start:342, line_end:342, byte_start:21785, byte_end:21888, decoder:utf8, sha256:"64f1b521a54707d98ae59b904571c02c8bc907967d8473549d9ecd93f84f21b6"}, segment{id:"seg_ebc6344074aa0def180b", path:"hermes/app/runtime/experiments/gemma4_tutor/docling/full-output/TeacherLessonGuides/Grade8/Grade8-3-10-Lesson-teacher-guide-/document.md", line_start:360, line_end:360, byte_start:23220, byte_end:23277, decoder:utf8, sha256:"9c2b42e999cd5a95d124530788858fc3dd5011e88ab182d13f28852f10e86e74"}, segment{id:"seg_712379073837c8a1db09", path:"hermes/app/runtime/exp