    defragged_task{evidence_sha256:"8f6d6e039c300edb47f221bd1991fa56240ee30d979c3b93d3b1ded9ad7b5f51", status:already_complete, blocker:none, complete_statement:"Here is a scatter plot that shows weights and fuel efficiencies of 20 different types of cars. If a car weighs 1,750 kg, would you expect its fuel efficiency to be closer to 22 mpg or to 28 mpg? Explain your reasoning.", statement_joiner:" ", statement_segments:[seg_117436eabcc1d6fd2c39, seg_7d1baa85ba493347bba7], referents:[], visuals:[], source_segments:[segment{id:"seg_117436eabcc1d6fd2c39", path:"hermes/app/runtime/experiments/gemma4_tutor/docling/full-output/TeacherLessonGuides/Grade8/Grade8-6-4-Lesson-teacher-guide-/document.md", line_start:96, line_end:96, byte_start:6151, byte_end:6245, decoder:utf8, sha256:"d4124283fc3a1e74fe0ea4dd703f69d0a79d1a6c1eb798ab634b1c1b74ad5ff7"}, segment{id:"seg_7d1baa85ba493347bba7", path:"hermes/app/runtime/experiments/gemma4_tutor/docling/full-output/TeacherLessonGuides/Grade8/Grade8-6-4-Lesson-teacher-guide-/document.md", line_start:117, line_end:117, byte_start:7240, byte_end:7363, decoder:utf8, sha256:"6bd2d02b9cbdcf1b0edaa21804535b23bc7aedfccb30c01fe34286257721af52"}], source_evidence:task_evidence(rule(docling_task_heading_exact_copy),source('hermes/app/runtime/experiments/gemma4_tutor/docling/full-output/TeacherLessonGuides/Grade8/Grade8-6-4-Lesson-teacher-guide-/document.md',lines(96,117)),position(student_task_statement(1)),excerpt("Here is a scatter plot that shows weights and fuel efficiencies of 20 different types of cars. If a car weighs 1,750 kg, would you expect its fuel efficiency to be closer to 22 mpg or to 28 mpg? Explain your reasoning."),extraction_status(complete),blocker(none),visual_provenance([visual_source(asset('hermes/app/runtime/experiments/gemma4_tutor/docling/full-output/TeacherLessonGuides/Grade8/Grade8-6-4-Lesson-teacher-guide-/document_artifacts/image_000014_9852fef28908537b92841544f2e813484c34fffa1a980366ba1d53e3ab65978f.png'),descrip