    defragged_task{evidence_sha256:"42646a75731244d2185e1fa0ee3b33d098a44a741f55709cd5c3069fe5bbaeaf", status:already_complete, blocker:none, complete_statement:"What factors or variables can influence the outside temperature in North America? Make a list of different factors. Write a sentence for each factor describing how changing it could change the temperature. Example: One factor is time of day. Often, after sunrise, the temperature increases, reaches a peak in the early afternoon, and then decreases.", statement_joiner:" ", statement_segments:[seg_9834a685696ed04f04a7, seg_5aa75a7425e695dd9e8a, seg_47ddc973bcde5ac8c430, seg_8f1b7c298e371846166c], referents:[], visuals:[], source_segments:[segment{id:"seg_9834a685696ed04f04a7", path:"hermes/app/runtime/experiments/gemma4_tutor/docling/full-output/TeacherLessonGuides/Grade8/Grade8-9-4-Lesson-teacher-guide-/document.md", line_start:109, line_end:109, byte_start:6817, byte_end:6898, decoder:utf8, sha256:"a25127a68ab712cdc877d159651022da7251d4bfcff62f4a0de995dad8d1c6eb"}, segment{id:"seg_5aa75a7425e695dd9e8a", path:"hermes/app/runtime/experiments/gemma4_tutor/docling/full-output/TeacherLessonGuides/Grade8/Grade8-9-4-Lesson-teacher-guide-/document.md", line_start:111, line_end:111, byte_start:6902, byte_end:6935, decoder:utf8, sha256:"32d4183a76fa3c4a8f17daf773007401f9c78405e3c87c5561e5fdc7dfe6ca3e"}, segment{id:"seg_47ddc973bcde5ac8c430", path:"hermes/app/runtime/experiments/gemma4_tutor/docling/full-output/TeacherLessonGuides/Grade8/Grade8-9-4-Lesson-teacher-guide-/document.md", line_start:112, line_end:112, byte_start:6938, byte_end:7027, decoder:utf8, sha256:"bd3c43bd53a6346a7df3318cb1803d1f83e34112e141d0ee018b403ba71138ca"}, segment{id:"seg_8f1b7c298e371846166c", path:"hermes/app/runtime/experiments/gemma4_tutor/docling/full-output/TeacherLessonGuides/Grade8/Grade8-9-4-Lesson-teacher-guide-/document.md", line_start:114, line_end:114, byte_start:7029, byte_end:7172, decoder:utf8, sha256:"16607add771eecdf305b77a5